from debim_ple_tools import read_png_rgba
import numpy as np

img = read_png_rgba('input/A-602.png')
gray = 0.299*img[:,:,0] + 0.587*img[:,:,1] + 0.114*img[:,:,2]

def trim_and_render(sub, thresh=160):
    bin_map = sub < thresh
    if not np.any(bin_map):
        return '(empty)'
    rmin, rmax = np.where(np.any(bin_map, axis=1))[0][[0, -1]]
    cmin, cmax = np.where(np.any(bin_map, axis=0))[0][[0, -1]]
    box = bin_map[rmin:rmax+1, cmin:cmax+1]
    if box.shape[0] % 2 != 0:
        box = np.vstack([box, np.zeros((1, box.shape[1]), dtype=bool)])
    lines = []
    for r in range(0, box.shape[0], 2):
        top = box[r]
        bot = box[r+1]
        line = []
        for c in range(box.shape[1]):
            t, b = top[c], bot[c]
            if t and b: line.append('█')
            elif t and not b: line.append('▀')
            elif not t and b: line.append('▄')
            else: line.append(' ')
        lines.append(''.join(line))
    return '\n'.join(lines)

col_bounds = [176, 275, 409, 517, 660, 847, 1098, 1201, 1354]
row_bounds = [113, 143, 163, 183]

for r_idx in range(len(row_bounds)-1):
    r0, r1 = row_bounds[r_idx], row_bounds[r_idx+1]
    print(f'=== ROW {r_idx} ===')
    for c_idx in range(len(col_bounds)-1):
        c0, c1 = col_bounds[c_idx], col_bounds[c_idx+1]
        sub = gray[r0+2:r1-2, c0+2:c1-2]
        res = trim_and_render(sub)
        print(f'R{r_idx}C{c_idx}:')
        print(res)
