import numpy as np

def label_components(binary_map):
    h, w = binary_map.shape
    visited = np.zeros((h, w), dtype=bool)
    components = []
    for r in range(h):
        for c in range(w):
            if binary_map[r, c] and not visited[r, c]:
                # BFS
                q = [(r, c)]
                visited[r, c] = True
                comp_pixels = []
                while q:
                    cr, cc = q.pop()
                    comp_pixels.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if binary_map[nr, nc] and not visited[nr, nc]:
                                    visited[nr, nc] = True
                                    q.append((nr, nc))
                components.append(comp_pixels)
    return components

print('BFS labeler works!')
